// Realistic lab environment around the cell, built at run time from Resources/SONAIR/lab.json
// (room shell with windows and a door, epoxy floor with the cell's hazard marking, guard fence, controller cabinet,
// e-stop, benches, whiteboard, cabinets, operator desk, ceiling LED panels and their lights).
// The file is generated by make_lab.py; the Blender check (verify_blender.py LAB=1) renders the same data.
// UV rule (shared with the Blender check): side faces u = viewer's right, v = up; top/bottom faces u = longer side.
using System;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.Rendering;

namespace Sonair
{
    [Serializable] public class LabPrim { public string type; public string name; public string mat; public float[] pos; public float[] rot; public float[] size; public float[] uv; public bool fit; public bool shadow; }
    [Serializable] public class LabLight { public string type; public float[] pos; public float[] rot; public float[] color; public float intensity; public float range; public float angle; public bool shadows; }
    [Serializable]
    public class LabFile
    {
        public string version; public string note; public SMaterial[] materials; public LabPrim[] prims; public LabLight[] lights;
        public float[] ambientSky; public float[] ambientEquator; public float[] ambientGround; public string[] hide;
        public float[] keyLightEuler; public float keyLightIntensity;
    }

    public static class SonairLab
    {
        public static LabFile Load()
        {
            var ta = Resources.Load<TextAsset>(SonairData.ResRoot + "lab");
            if (ta == null) { Debug.LogWarning("[SONAIR] Resources/SONAIR/lab.json missing: no lab environment"); return null; }
            return JsonUtility.FromJson<LabFile>(ta.text);
        }

        /// <summary>Builds the lab under parent (the cell root, so it shares the cell's frame). Returns the lab root.</summary>
        public static Transform Build(Transform parent, LabFile lab)
        {
            var root = new GameObject("Lab").transform;
            root.SetParent(parent, false);
            var mats = new Dictionary<string, Material>();
            foreach (var m in lab.materials) mats[m.name] = MakeTiledMaterial(m);
            foreach (var p in lab.prims)
            {
                var go = new GameObject(p.name);
                go.transform.SetParent(root, false);
                go.transform.localPosition = SonairData.V3(p.pos);
                go.transform.localRotation = SonairData.Q(p.rot);
                var size = SonairData.V3(p.size);
                var uv = new Vector2(p.uv != null && p.uv.Length > 0 ? p.uv[0] : 1f, p.uv != null && p.uv.Length > 1 ? p.uv[1] : 1f);
                go.AddComponent<MeshFilter>().sharedMesh = p.type == "cyl" ? Cylinder(size, uv) : Box(size, uv, p.fit);
                var mr = go.AddComponent<MeshRenderer>();
                Material mm;
                mr.sharedMaterial = mats.TryGetValue(p.mat, out mm) ? mm : null;
                mr.shadowCastingMode = p.shadow ? ShadowCastingMode.On : ShadowCastingMode.Off;
            }
            foreach (var l in lab.lights)
            {
                var go = new GameObject("LabLight_" + l.type);
                go.transform.SetParent(root, false);
                go.transform.localPosition = SonairData.V3(l.pos);
                go.transform.localRotation = Quaternion.Euler(l.rot[0], l.rot[1], l.rot[2]);
                var li = go.AddComponent<Light>();
                li.type = l.type == "Spot" ? LightType.Spot : LightType.Point;
                li.color = new Color(l.color[0], l.color[1], l.color[2]);
                li.intensity = l.intensity; li.range = l.range;
                if (li.type == LightType.Spot) li.spotAngle = l.angle;
                li.shadows = l.shadows ? LightShadows.Soft : LightShadows.None;
            }
            // ambient light from the room, and one reflection probe so metal parts reflect the lab, not the sky
            RenderSettings.ambientMode = AmbientMode.Trilight;
            RenderSettings.ambientSkyColor = Col(lab.ambientSky); RenderSettings.ambientEquatorColor = Col(lab.ambientEquator);
            RenderSettings.ambientGroundColor = Col(lab.ambientGround);
            var probe = new GameObject("LabReflectionProbe").AddComponent<ReflectionProbe>();
            probe.transform.SetParent(root, false);
            probe.transform.localPosition = new Vector3(0f, 0.6f, 0.4f);
            probe.size = new Vector3(8f, 3.4f, 9f);
            probe.mode = ReflectionProbeMode.Realtime;
            probe.refreshMode = ReflectionProbeRefreshMode.ViaScripting;
            probe.timeSlicingMode = ReflectionProbeTimeSlicingMode.NoTimeSlicing;
            probe.RenderProbe();
            return root;
        }

        static Color Col(float[] c) { return c == null || c.Length < 3 ? Color.gray : new Color(c[0], c[1], c[2]); }

        static readonly Dictionary<string, Texture2D> tiled = new Dictionary<string, Texture2D>();
        static Texture2D TiledTexture(string key)
        {
            Texture2D t;
            if (tiled.TryGetValue(key, out t) && t != null) return t;
            var ta = Resources.Load<TextAsset>(SonairData.ResRoot + "Textures/" + key);
            if (ta == null) { Debug.LogWarning("[SONAIR] lab texture not found: " + key); return null; }
            t = new Texture2D(2, 2, TextureFormat.RGBA32, true) { name = key };
            t.LoadImage(ta.bytes);
            t.wrapMode = TextureWrapMode.Repeat; t.filterMode = FilterMode.Trilinear; t.anisoLevel = 8;
            tiled[key] = t;
            return t;
        }

        static Material MakeTiledMaterial(SMaterial s)
        {
            var m = new Material(SonairData.LitShader()) { name = "SONAIR_" + s.name };
            var c = new Color(s.color[0], s.color[1], s.color[2], s.color[3]);
            m.color = c;
            if (m.HasProperty("_BaseColor")) m.SetColor("_BaseColor", c);
            if (m.HasProperty("_Metallic")) m.SetFloat("_Metallic", s.metallic);
            if (m.HasProperty("_Glossiness")) m.SetFloat("_Glossiness", s.smoothness);
            if (m.HasProperty("_Smoothness")) m.SetFloat("_Smoothness", s.smoothness);
            if (!string.IsNullOrEmpty(s.texture))
            {
                var tex = TiledTexture(s.texture);
                if (tex != null)
                {
                    m.mainTexture = tex;
                    if (m.HasProperty("_BaseMap")) m.SetTexture("_BaseMap", tex);
                    if (m.HasProperty("_BaseColorMap")) m.SetTexture("_BaseColorMap", tex);
                }
            }
            if (s.emission != null && s.emission.Length >= 3 && (s.emission[0] + s.emission[1] + s.emission[2]) > 0f)
            {
                var e = new Color(s.emission[0], s.emission[1], s.emission[2]);
                m.EnableKeyword("_EMISSION");
                if (m.HasProperty("_EmissionColor")) m.SetColor("_EmissionColor", e);
                if (m.HasProperty("_EmissiveColor")) m.SetColor("_EmissiveColor", e * 3f);   // HDRP
                if (m.mainTexture != null && m.HasProperty("_EmissionMap")) m.SetTexture("_EmissionMap", m.mainTexture);
                m.globalIlluminationFlags = MaterialGlobalIlluminationFlags.RealtimeEmissive;
            }
            if (c.a < 0.999f) SonairData.MakeTransparent(m);
            return m;
        }

        // ------------------------------------------------------------------ meshes with physical UVs
        static readonly Vector3[] Normals = { Vector3.right, Vector3.left, Vector3.up, Vector3.down, Vector3.forward, Vector3.back };

        public static Mesh Box(Vector3 s, Vector2 uvMetres, bool fit)
        {
            var V = new List<Vector3>(); var N = new List<Vector3>(); var U = new List<Vector2>(); var I = new List<int>();
            Vector3 h = 0.5f * s;
            foreach (var n in Normals)
            {
                Vector3 a, b;                                   // in-plane axes: a -> u, b -> v
                if (Mathf.Abs(n.y) > 0.5f)
                {
                    a = s.x >= s.z ? Vector3.right : Vector3.forward;
                    b = s.x >= s.z ? Vector3.forward : Vector3.right;
                }
                else { a = Vector3.Cross(Vector3.up, -n); b = Vector3.up; }   // viewer's right and up
                float la = Mathf.Abs(Vector3.Dot(a, s)), lb = Mathf.Abs(Vector3.Dot(b, s));
                Vector3 c0 = Vector3.Scale(n, h);
                int o = V.Count;
                Vector2[] corners = { new Vector2(-1, -1), new Vector2(1, -1), new Vector2(1, 1), new Vector2(-1, 1) };
                foreach (var k in corners)
                {
                    V.Add(c0 + a * (0.5f * la * k.x) + b * (0.5f * lb * k.y)); N.Add(n);
                    float u = fit ? 0.5f * (k.x + 1f) : 0.5f * (k.x + 1f) * la / Mathf.Max(1e-4f, uvMetres.x);
                    float v = fit ? 0.5f * (k.y + 1f) : 0.5f * (k.y + 1f) * lb / Mathf.Max(1e-4f, uvMetres.y);
                    U.Add(new Vector2(u, v));
                }
                Vector3 cr = Vector3.Cross(V[o + 1] - V[o], V[o + 2] - V[o]);
                if (Vector3.Dot(cr, n) > 0) { I.Add(o); I.Add(o + 1); I.Add(o + 2); I.Add(o); I.Add(o + 2); I.Add(o + 3); }
                else { I.Add(o); I.Add(o + 2); I.Add(o + 1); I.Add(o); I.Add(o + 3); I.Add(o + 2); }
            }
            var m = new Mesh { name = "LabBox" };
            m.SetVertices(V); m.SetNormals(N); m.SetUVs(0, U); m.SetTriangles(I, 0); m.RecalculateBounds(); m.RecalculateTangents();
            return m;
        }

        /// <summary>Vertical cylinder (axis = local y): s = (diameter, height, diameter).</summary>
        public static Mesh Cylinder(Vector3 s, Vector2 uvMetres, int seg = 32)
        {
            var V = new List<Vector3>(); var N = new List<Vector3>(); var U = new List<Vector2>(); var I = new List<int>();
            float r = 0.5f * s.x, hh = 0.5f * s.y;
            for (int i = 0; i <= seg; i++)
            {
                float a = 2f * Mathf.PI * i / seg; var d = new Vector3(Mathf.Cos(a), 0f, Mathf.Sin(a));
                V.Add(d * r + Vector3.down * hh); N.Add(d); U.Add(new Vector2((float)i / seg, 0f));
                V.Add(d * r + Vector3.up * hh); N.Add(d); U.Add(new Vector2((float)i / seg, 1f));
            }
            for (int i = 0; i < seg; i++)
            {
                int o = 2 * i;
                AddTri(V, I, o, o + 2, o + 1, N[o]); AddTri(V, I, o + 1, o + 2, o + 3, N[o]);
            }
            for (int cap = 0; cap < 2; cap++)
            {
                var n = cap == 0 ? Vector3.up : Vector3.down; int c = V.Count;
                V.Add(n * hh); N.Add(n); U.Add(new Vector2(0.5f, 0.5f));
                for (int i = 0; i <= seg; i++)
                {
                    float a = 2f * Mathf.PI * i / seg; var d = new Vector3(Mathf.Cos(a), 0f, Mathf.Sin(a));
                    V.Add(d * r + n * hh); N.Add(n); U.Add(new Vector2(0.5f + 0.5f * d.x, 0.5f + 0.5f * d.z));
                }
                for (int i = 0; i < seg; i++) AddTri(V, I, c, c + 1 + i, c + 2 + i, n);
            }
            var m = new Mesh { name = "LabCylinder" };
            m.SetVertices(V); m.SetNormals(N); m.SetUVs(0, U); m.SetTriangles(I, 0); m.RecalculateBounds();
            return m;
        }

        static void AddTri(List<Vector3> V, List<int> I, int a, int b, int c, Vector3 outward)
        {
            Vector3 cr = Vector3.Cross(V[b] - V[a], V[c] - V[a]);
            Vector3 mid = (V[a] + V[b] + V[c]) / 3f;
            Vector3 n = outward.sqrMagnitude > 0 ? outward : mid;
            if (Vector3.Dot(cr, n) > 0) { I.Add(a); I.Add(b); I.Add(c); } else { I.Add(a); I.Add(c); I.Add(b); }
        }
    }
}
